/**
 * ERC-7730 clear signing for the review screen.
 *
 * Source data: a curated snapshot of the ERC-7730 clear-signing
 * registry, generated by scripts/generate-clear-signing-snapshot.mjs
 * (licence CC0 1.0). The surveyed checkout is the okxlabs fork
 * (okxlabs/clear-signing-erc7730-registry @ 3d60345, which merges
 * ethereum:master); the canonical upstream is the Ethereum
 * Foundation registry at
 * https://github.com/ethereum/clear-signing-erc7730-registry — the
 * fork was used because it is the surveyed checkout, and its content
 * is the upstream registry as merged. A future refresh should pull
 * from upstream and re-run the generator.
 *
 * Scope, stated honestly:
 * - Only the snapshot's functions resolve: the generic ERC-20
 *   descriptors (transfer/approve, which apply to any ERC-20
 *   contract per the registry's own ercs/ files) and the vendored
 *   per-contract functions (1inch AggregationRouterV6). The full
 *   registry is 6.1 MB (814 calldata entries; the index alone is
 *   88 KB) and cannot ship in a bundle with ~4.8 KB of headroom,
 *   so the snapshot is a curated subset — see the generator.
 * - The decoder handles address and uint parameters only — the
 *   only display types in the snapshot. Anything else (tuples,
 *   dynamic bytes, signed ints, bools) resolves to no match, so
 *   Safe execTransaction is not vendored: it needs dynamic bytes
 *   decoding the bundle has no room for.
 * - Values render generically by ABI type. The registry's $ref
 *   formatters (tokenAmount with token metadata, addressName/ENS
 *   lookup, date/enum rendering) are NOT implemented: an amount
 *   renders as a human decimal only when the caller passes the
 *   token's decimals/symbol, and addresses render as plain hex.
 * - EIP-712 is not wired: the wallet has no EIP-712 signing
 *   surface (evm-typed-data.ts was deleted with no consumer), so
 *   there is nothing to display it on.
 * - When nothing matches, resolveContractCall returns null and the
 *   review screen falls back to the raw calldata. A reading is
 *   never invented.
 */

import { keccak256, stringToHex } from 'viem';
import snapshotJson from './clear-signing-snapshot.json';

// Compact snapshot schema (see the generator): function {s,i,p},
// param {t,l,m?,h?}, contract {n,a,c,f}. Display types: address | uint.
// h (hidden) marks a positional placeholder: the parameter stays in
// p so decoding stays positional, but it is never shown as a row.
// The 1inch `token` param is the only hidden one — the registry has
// no display field for it (it appears only as tokenPath inside the
// amount field), so the snapshot shows the registry's 4 rows.
type ClearSigningParam = {
  readonly t: 'address' | 'uint';
  readonly l: string;
  readonly m?: boolean;
  readonly h?: boolean;
};

type ClearSigningFunction = {
  readonly s: string;
  readonly i: string;
  readonly p: readonly ClearSigningParam[];
};

type ClearSigningContract = {
  readonly n: string;
  readonly a: string;
  readonly c: readonly number[];
  readonly f: readonly ClearSigningFunction[];
};

type ClearSigningSnapshot = {
  readonly g: readonly ClearSigningFunction[];
  readonly c: readonly ClearSigningContract[];
};

const SNAPSHOT = snapshotJson as unknown as ClearSigningSnapshot;

type ClearSigningToken = {
  readonly decimals: number;
  readonly symbol: string;
};

export type ClearSigningInput = {
  readonly chainId: number;
  readonly contract: string;
  readonly data: string;
  readonly token?: ClearSigningToken;
};

type ClearSigningRow = {
  readonly label: string;
  readonly value: string;
};

type ClearSigningResult = {
  /** Per-contract name, or null for a generic (standard) descriptor. */
  readonly contractName: string | null;
  readonly intent: string;
  readonly functionName: string;
  readonly rows: readonly ClearSigningRow[];
};

const HEX_DATA_PATTERN = /^0x(?:[0-9a-fA-F]{2})*$/;
const ADDRESS_PATTERN = /^0x[0-9a-fA-F]{40}$/;

/**
 * Split "name(type name, type name)" into its name and canonical
 * parameter types. The registry stores display signatures with
 * parameter names ("transfer(address _to, uint256 _value)"), but the
 * selector and the ABI decoding use the canonical form with types
 * only ("transfer(address,uint256)") — so the name is stripped here.
 * Widths are kept: the selector for uint8 differs from uint256.
 */
function parseSignature(
  signature: string,
): { name: string; types: readonly string[] } | null {
  const open = signature.indexOf('(');
  const close = signature.lastIndexOf(')');
  if (open < 1 || close !== signature.length - 1) return null;
  const name = signature.slice(0, open);
  const inner = signature.slice(open + 1, close);
  const rawParams = inner === '' ? [] : inner.split(',');
  const types: string[] = [];
  for (const raw of rawParams) {
    // Tuples "(...)", arrays "type[]" and every other type resolve
    // to no match — the decoder handles address and uint only.
    if (raw.includes('(') || raw.includes(')') || raw.trimEnd().endsWith(']')) {
      return null;
    }
    const type = raw.trim().split(/\s+/)[0];
    if (type === 'address' || (type !== undefined && /^uint[0-9]*$/.test(type))) {
      types.push(type);
    } else {
      return null;
    }
  }
  return { name, types };
}

/** First 4 bytes of keccak256(canonical signature), as "0x" + 8 hex chars. */
function selectorOf(signature: string): string | null {
  const parsed = parseSignature(signature);
  if (parsed === null) return null;
  const canonical = `${parsed.name}(${parsed.types.join(',')})`;
  return keccak256(stringToHex(canonical)).slice(0, 10);
}

/**
 * Decode calldata against a function signature into one raw string
 * per parameter (addresses as 0x hex, integers as decimal strings).
 * Returns null when the data does not fit the signature — never a
 * partial reading.
 */
export function decodeCalldata(
  data: string,
  signature: string,
): readonly string[] | null {
  const parsed = parseSignature(signature);
  if (parsed === null) return null;
  const selector = selectorOf(signature);
  if (selector === null) return null;
  if (!HEX_DATA_PATTERN.test(data) || data.length < 10) return null;
  if (data.slice(0, 10).toLowerCase() !== selector) return null;
  const body = data.slice(10);
  // Exact length: trailing words are not part of the signature, so
  // calldata with extra bytes does not fit it and must not resolve
  // as a clean reading of the first n words.
  if (body.length !== parsed.types.length * 64) {
    return null;
  }
  const values: string[] = [];
  for (let i = 0; i < parsed.types.length; i += 1) {
    const word = body.slice(i * 64, i * 64 + 64);
    values.push(
      parsed.types[i] === 'address'
        ? `0x${word.slice(24)}`
        : BigInt(`0x${word}`).toString(10),
    );
  }
  return values;
}

/** Insert a decimal point into base units ("1500000", 6 -> "1.5"). */
export function formatBaseUnits(amount: string, decimals: number): string {
  if (!/^[0-9]+$/.test(amount) || decimals < 0) return amount;
  if (decimals === 0) return amount;
  const padded = amount.padStart(decimals + 1, '0');
  const whole = padded.slice(0, padded.length - decimals);
  const fraction = padded.slice(padded.length - decimals).replace(/0+$/, '');
  return fraction === '' ? whole : `${whole}.${fraction}`;
}

function formatValue(
  raw: string,
  param: ClearSigningParam,
  token?: ClearSigningToken,
): string {
  // Display type address over a uint256 ABI word (1inch packs
  // addresses as uint256): render the low 20 bytes as the address.
  if (param.t === 'address' && /^[0-9]+$/.test(raw)) {
    return `0x${BigInt(raw).toString(16).padStart(64, '0').slice(24)}`;
  }
  if (param.m === true && token !== undefined) {
    return `${formatBaseUnits(raw, token.decimals)} ${token.symbol}`;
  }
  return raw;
}

/**
 * Resolve an EVM contract call against the vendored ERC-7730
 * snapshot. Per-contract entries match on address + chain; generic
 * (standard ERC-20) entries match on function alone. Returns null
 * for anything unknown or malformed — the caller shows the raw data.
 */
export function resolveContractCall(
  input: ClearSigningInput,
): ClearSigningResult | null {
  if (
    !Number.isInteger(input.chainId) ||
    input.chainId <= 0 ||
    !ADDRESS_PATTERN.test(input.contract) ||
    !HEX_DATA_PATTERN.test(input.data) ||
    input.data.length < 10
  ) {
    return null;
  }
  const selector = input.data.slice(0, 10).toLowerCase();
  const contract = input.contract.toLowerCase();

  let matched: {
    contractName: string | null;
    fn: ClearSigningFunction;
  } | null = null;
  for (const entry of SNAPSHOT.c) {
    if (
      entry.a.toLowerCase() !== contract ||
      !entry.c.includes(input.chainId)
    ) {
      continue;
    }
    const fn = entry.f.find((candidate) => {
      const candidateSelector = selectorOf(candidate.s);
      return (
        candidateSelector !== null &&
        candidateSelector.toLowerCase() === selector
      );
    });
    if (fn !== undefined) {
      matched = { contractName: entry.n, fn };
      break;
    }
  }
  if (matched === null) {
    const fn = SNAPSHOT.g.find((candidate) => {
      const candidateSelector = selectorOf(candidate.s);
      return (
        candidateSelector !== null &&
        candidateSelector.toLowerCase() === selector
      );
    });
    if (fn !== undefined) matched = { contractName: null, fn };
  }
  if (matched === null) return null;

  const values = decodeCalldata(input.data, matched.fn.s);
  if (values === null || values.length !== matched.fn.p.length) {
    return null;
  }
  // decodeCalldata already parsed the signature, so the name is
  // everything before "(". Rows are positional: p stays aligned with
  // the signature, and hidden params (h) are skipped, not shown.
  return {
    contractName: matched.contractName,
    intent: matched.fn.i,
    functionName: matched.fn.s.slice(0, matched.fn.s.indexOf('(')),
    rows: matched.fn.p
      .map((param, index) => ({ param, value: values[index] as string }))
      .filter(({ param }) => param.h !== true)
      .map(({ param, value }) => ({
        label: param.l,
        value: formatValue(value, param, input.token),
      })),
  };
}
